package com.bank.shortener;

import java.time.*;
import java.util.logging.*;

public class ShortenerDemo {
    private static final Logger log = Logger.getLogger("Shortener");
    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        MappingRepository repo = new MappingRepository();
        Cache cache = new Cache();
        UrlShortenerService service = new UrlShortenerService(repo, cache, new Base62Codec());

        // Rajesh's long statement link
        String longUrl = "https://nbi.in/statements?acct=SAV2001&token=eyJhbGciOi...&month=2026-10";
        String key = service.shorten(longUrl, null, null, "SAV2001");
        log.info(() -> "Short key for statement: " + key);

        // Resolve several times — first is DB miss, rest are cache hits
        for (int i = 0; i < 3; i++) {
            String resolved = service.resolve(key);
            log.info(() -> "Resolved -> " + resolved);
        }
        log.info(() -> "Clicks so far: " + service.clickCount(key));

        // Custom alias for a loan campaign, expiring in 7 days
        String alias = service.shorten("https://nbi.in/loan-offer-diwali",
                "loan-offer", LocalDateTime.now().plusDays(7), "MARKETING");
        log.info(() -> "Custom alias created: " + alias);

        // An already-expired link is rejected
        String expiredKey = service.shorten("https://nbi.in/old",
                "old-promo", LocalDateTime.now().minusDays(1), "MARKETING");
        String expiredResolve = service.resolve(expiredKey);
        log.info(() -> "Expired link resolves to: " + expiredResolve);
    }
}

