package com.bank.shortener;

import java.time.LocalDateTime;

public class UrlMapping {
    private final long id;
    private final String shortKey;
    private final String longUrl;
    private final String owner;
    private long clicks;
    private final LocalDateTime expiresAt; // null = never expires

    public UrlMapping(long id, String shortKey, String longUrl, String owner, LocalDateTime expiresAt) {
        this.id = id;
        this.shortKey = shortKey;
        this.longUrl = longUrl;
        this.owner = owner;
        this.expiresAt = expiresAt;
    }
    public long getId() { return id; }
    public String getShortKey() { return shortKey; }
    public String getLongUrl() { return longUrl; }
    public String getOwner() { return owner; }
    public long getClicks() { return clicks; }
    public void incrementClicks() { clicks++; }
    public boolean isExpired() {
        return expiresAt != null && LocalDateTime.now().isAfter(expiresAt);
    }
}
