package com.bank.shortener;

import java.util.*;
import java.util.concurrent.atomic.AtomicLong;

public class MappingRepository {
    private final Map<String, UrlMapping> byKey = new HashMap<>();
    private final AtomicLong sequence = new AtomicLong(1000);  // numeric id source

    public long nextId() { return sequence.incrementAndGet(); }
    public boolean keyExists(String key) { return byKey.containsKey(key); }
    public void save(UrlMapping m) { byKey.put(m.getShortKey(), m); }
    public UrlMapping findByKey(String key) { return byKey.get(key); }
}
```

