// ─── File: UrlShortenerService.java ───
package com.bank.shortener;

import java.time.LocalDateTime;
import java.util.logging.*;

public class UrlShortenerService {
    private static final Logger log = Logger.getLogger("Shortener");
    private final MappingRepository repo;
    private final Cache cache;
    private final Base62Codec codec;

    public UrlShortenerService(MappingRepository repo, Cache cache, Base62Codec codec) {
            this.repo = repo;
            this.cache = cache
            this.codec = codec;
    }

    // create a short key; customAlias and expiry are optional (nullable)
    public String shorten(String longUrl, String customAlias, LocalDateTime expiry, String owner) {
        long id = repo.nextId();
        String key;
        if (customAlias != null) {
            if (repo.keyExists(customAlias))
                throw new IllegalStateException("Alias already taken: " + customAlias);
            key = customAlias;
        } else {
            key = codec.encode(id);
        }
        repo.save(new UrlMapping(id, key, longUrl, owner, expiry));
        log.info(() -> "Stored mapping " + key + " -> " + longUrl);
        return key;
    }

    // cache-aside resolve; records a click; honours expiry
    public String resolve(String shortKey) {
        String cached = cache.get(shortKey);
        if (cached != null) {
            log.fine(() -> "cache HIT " + shortKey);
            recordClick(shortKey);
            return cached;
        }
        log.fine(() -> "cache MISS " + shortKey);
        UrlMapping m = repo.findByKey(shortKey);
            if (m == null) { log.warning(() -> "Unknown key " + shortKey);
            return null; }
            if (m.isExpired()) { log.warning(() -> "Expired key " + shortKey);
            return null; }
        cache.put(shortKey, m.getLongUrl());
        recordClick(shortKey);
        return m.getLongUrl();
    }

    private void recordClick(String key) {
        UrlMapping m = repo.findByKey(key);
        if (m != null) m.incrementClicks(); // in production: async via Kafka
    }

    public long clickCount(String key) {
        UrlMapping m = repo.findByKey(key);
        return m == null ? 0 : m.getClicks();
    }
}
```
